"""Bounded, cancellable paragraph requests with a shared model circuit breaker."""

import asyncio
import contextlib
import hashlib
import json
import logging
import re
import threading
import time
from logging.handlers import RotatingFileHandler

import httpx

from pdf2zh.local_config import DATA_ROOT, decode_key, load_pool_settings, validate_pool_settings
from pdf2zh.translator import BaseTranslator


class TranslationCancelled(RuntimeError):
    pass


class ModelPoolExhausted(RuntimeError):
    pass


class _EndpointFailure(Exception):
    def __init__(self, reason, retry_after=0):
        super().__init__(reason)
        self.reason = reason
        self.retry_after = retry_after


_log = logging.getLogger("pdf2zh.local_failover")
_log_lock = threading.Lock()


def _event(message):
    with _log_lock:
        if not _log.handlers:
            folder = DATA_ROOT / "logs"
            folder.mkdir(exist_ok=True)
            handler = RotatingFileHandler(folder / "model_failover.log", maxBytes=1_000_000, backupCount=2, encoding="utf-8")
            handler.setFormatter(logging.Formatter("%(asctime)s %(message)s"))
            _log.addHandler(handler)
            _log.setLevel(logging.INFO)
            _log.propagate = False
    _log.info(message)


class ModelPool:
    def __init__(self, settings=None, cancel_event=None, on_status=None):
        settings = settings if settings is not None else load_pool_settings()
        self.profiles = [dict(profile) for profile in validate_pool_settings(settings)]
        self.timeout = float(settings.get("request_timeout", 30))
        self.cooldown = float(settings.get("cooldown", 60))
        self.qps = float(settings.get("qps", 10))
        self.cancel_event = cancel_event or threading.Event()
        self.on_status = on_status
        self._lock = threading.Lock()
        self._preferred = 0
        self._blocked_until = [0.0] * len(self.profiles)
        self._next_request = 0.0
        self._fatal = None
        # Loading the CA bundle for every paragraph is expensive on Windows.
        # The immutable context is safe to share across request threads.
        self._ssl_context = httpx.create_ssl_context()
        identity = [{key: profile.get(key) for key in ("base_url", "model", "api_key", "disable_thinking")} for profile in self.profiles]
        self.cache_identity = hashlib.sha256(json.dumps(identity, sort_keys=True).encode()).hexdigest()

    def check_cancelled(self):
        if self.cancel_event.is_set():
            raise TranslationCancelled("翻译已取消")
        if self._fatal is not None:
            raise ModelPoolExhausted(self._fatal)

    def _status(self, message):
        _event(message)
        if self.on_status:
            self.on_status(message)

    def _name(self, index):
        return re.sub(r"[\r\n\t]", " ", str(self.profiles[index].get("name") or f"模型 {index + 1}"))[:100]

    def _pick(self, tried):
        with self._lock:
            now = time.monotonic()
            order = [self._preferred] + [i for i in range(len(self.profiles)) if i != self._preferred]
            return next((i for i in order if i not in tried and self._blocked_until[i] <= now), None)

    def _rate_limit(self):
        if not self.qps:
            self.check_cancelled()
            return
        while True:
            self.check_cancelled()
            with self._lock:
                now = time.monotonic()
                delay = self._next_request - now
                if delay <= 0:
                    self._next_request = now + 1.0 / self.qps
                    return
            self.cancel_event.wait(min(delay, 0.05))

    async def _request(self, profile, messages):
        url = profile["base_url"].strip().rstrip("/")
        if not url.endswith("/chat/completions"):
            url += "/chat/completions"
        headers = {"Content-Type": "application/json"}
        api_key = decode_key(profile.get("api_key", ""))
        if api_key:
            headers["Authorization"] = f"Bearer {api_key}"
        payload = {"model": profile["model"].strip(), "messages": messages, "temperature": 0, "stream": False}
        if profile.get("disable_thinking", False):
            payload["enable_thinking"] = False
        request_task = None
        try:
            # Includes connecting, headers, and the entire body, even a trickling body.
            async with asyncio.timeout(self.timeout):
                async with httpx.AsyncClient(verify=self._ssl_context, timeout=httpx.Timeout(self.timeout, connect=min(10, self.timeout))) as client:
                    request_task = asyncio.create_task(client.post(url, headers=headers, json=payload))
                    try:
                        while not request_task.done():
                            await asyncio.wait({request_task}, timeout=0.05)
                            self.check_cancelled()
                        response = await request_task
                    finally:
                        if not request_task.done():
                            request_task.cancel()
                        with contextlib.suppress(asyncio.CancelledError, Exception):
                            await request_task
                    if response.status_code >= 400:
                        try:
                            retry_after = min(3600, max(0, float(response.headers.get("Retry-After", 0))))
                        except ValueError:
                            retry_after = 0
                        raise _EndpointFailure(f"HTTP {response.status_code}", retry_after)
                    try:
                        content = response.json()["choices"][0]["message"]["content"]
                    except (ValueError, KeyError, IndexError, TypeError):
                        raise _EndpointFailure("返回格式异常") from None
                    if not isinstance(content, str):
                        raise _EndpointFailure("返回空内容")
                    content = re.sub(r"^\s*<think>.*?</think>\s*", "", content, flags=re.DOTALL).strip()
                    if not content:
                        raise _EndpointFailure("返回空内容")
                    return content
        except (TimeoutError, httpx.TimeoutException):
            raise _EndpointFailure(f"请求超时（{self.timeout:g} 秒）") from None
        except httpx.HTTPError:
            # Raw HTTP exceptions can include credentials or document text.
            raise _EndpointFailure("网络连接异常") from None

    def translate(self, messages):
        tried = set()
        failures = []
        while True:
            self.check_cancelled()
            index = self._pick(tried)
            if index is None:
                detail = "；".join(failures) or "所有模型正在故障冷却中"
                message = f"当前没有可用模型：{detail}。已停止本次任务；完成的段落保留在缓存，可稍后重试。"
                with self._lock:
                    if self._fatal is None:
                        self._fatal = message
                raise ModelPoolExhausted(message)
            self._rate_limit()
            # Another paragraph might have marked this model unavailable while queued.
            with self._lock:
                if self._blocked_until[index] > time.monotonic():
                    continue
            tried.add(index)
            try:
                result = asyncio.run(self._request(self.profiles[index], messages))
            except _EndpointFailure as error:
                with self._lock:
                    self._blocked_until[index] = max(self._blocked_until[index], time.monotonic() + max(self.cooldown, error.retry_after))
                failures.append(f"{self._name(index)}：{error.reason}")
                next_index = self._pick(tried)
                action = f"切换到 {self._name(next_index)}，重试当前段落" if next_index is not None else "没有可用的备用模型"
                self._status(f"{self._name(index)} {error.reason}；{action}")
                continue
            with self._lock:
                # A late success must not reopen a model another request just blocked.
                if self._blocked_until[index] <= time.monotonic():
                    self._preferred = index
            return result


class FailoverTranslator(BaseTranslator):
    name = "local-model-pool"
    envs = {}
    CustomPrompt = True
    manages_retries = True

    def __init__(self, lang_in, lang_out, model=None, envs=None, prompt=None, ignore_cache=False):
        self.pool = (envs or {}).get("_LOCAL_MODEL_POOL") or ModelPool()
        super().__init__(lang_in, lang_out, self.pool.cache_identity, ignore_cache)
        self.prompttext = prompt
        self.add_cache_impact_parameters("prompt", self.prompt("", prompt))

    def translate(self, text, ignore_cache=False):
        self.pool.check_cancelled()
        return super().translate(text, ignore_cache)

    def do_translate(self, text):
        return self.pool.translate(self.prompt(text, self.prompttext))

    def get_formular_placeholder(self, id):
        return "{{v" + str(id) + "}}"

    def get_rich_text_left_placeholder(self, id):
        return self.get_formular_placeholder(id)

    def get_rich_text_right_placeholder(self, id):
        return self.get_formular_placeholder(id + 1)


def worker_envs(params, cancel_event, on_status):
    envs = dict(params.get("envs", {}))
    if params["translator"].name == FailoverTranslator.name:
        envs["_LOCAL_MODEL_POOL"] = ModelPool(params.get("local_models"), cancel_event, on_status)
    return envs
